use cryprot_codes::ExConvCode;
use cryprot_core::Block;
use sha2::{Digest, Sha256};
#[unsafe(no_mangle)]
pub extern "C" fn encode(seed: u32) -> u64 {
    let mut blocks: Vec<Block> = (0..1_048_576_u128)
        .map(|index| Block::new(index.wrapping_mul(0x1684934101347340963727634173201_u128)
            .wrapping_add(u128::from(seed)).to_le_bytes())).collect();
    ExConvCode::new(524_288).dual_encode(&mut blocks);
    let mut digest = Sha256::new();
    for block in &blocks { digest.update(block.as_bytes()); }
    u64::from_le_bytes(digest.finalize()[..8].try_into().unwrap())
}

