import { readFile, writeFile } from 'node:fs/promises';
import { performance } from 'node:perf_hooks';
const file = process.argv[2];
const bytes = await readFile(file);
const { instance } = await WebAssembly.instantiate(bytes, {});
const cases = [];
for (const seed of [0, 1, 19, 1234, 0, 1, 19, 1234]) {
  const start = performance.now();
  const digest = instance.exports.encode(seed);
  cases.push({seed, digest_prefix_hex: BigInt.asUintN(64, digest).toString(16), elapsed_ms: performance.now()-start});
}
await writeFile(process.argv[3], JSON.stringify({scope: 'Public ExConv full-sized encoding in Node Wasm. Synthetic public inputs, SHA-256 prefix over the full output. Includes input fill and hashing. No network or Workers attribution.', cases}, null, 2));
console.log(cases);
